ones = 'one two three four five six seven eight nine'.split(' ')

def num_to_word(x):
	if x < 10:
		return ones[x - 1]
	if x == 10:
		return 'ten'
	if x < 20:
		return 'eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen'.split(' ')[x - 11]
	ten = x // 10
	one = x % 10
	tens = 'twenty thirty forty fifty'.split(' ')
	if one == 0:
		return tens[ten - 2]
	else:
		return tens[ten - 2] + ' ' + ones[one - 1]
h = int(input())
m = int(input())
if m > 30:
	if m == 59:
		print('one minute to %s' % num_to_word(h + 1 if h != 12 else 1))
	elif m == 45:
		print('quarter to %s' % num_to_word(h + 1 if h != 12 else 1))
	else:
		print('%s minutes to %s' % (num_to_word(60 - m), num_to_word(h + 1 if h != 12 else 1)))
elif m == 0:
	print("%s o' clock" % num_to_word(h))
elif m == 1:
	print('one minute past %s' % num_to_word(h))
elif m == 15:
	print('quarter past %s' % num_to_word(h))
elif m == 30:
	print('half past %s' % num_to_word(h))
else:
	print('%s minutes past %s' % (num_to_word(m), num_to_word(h)))
